import json
from collections import Counter


def main():
    counts = Counter()
    with open("app.log") as f:
        for line in f:
            level = line.split(None, 1)[0]
            if level:
                counts[level] += 1
    report = {level: counts[level] for level in ("INFO", "WARN", "ERROR")}
    with open("report.json", "w") as f:
        json.dump(report, f, indent=2)
    print(report)


if __name__ == "__main__":
    main()

